// CSD_RATIONALE_BEGIN
// Root cause of 52% accuracy: avg only 8.68 generated tokens total, meaning
// ~3 constrained SQL tokens. The LM picks EOS immediately after a trivially
// short SQL like "SELECT city FROM employee", which the SQL parser accepts as
// complete. RegenerateUnitOnGroundingFailure (attempt 61, best) still
// terminates on early EOS.
//
// Fix: Explicitly IGNORE EOS for the first `minTokens` constrained steps.
// Only accept EOS (a) after at least 25 constrained tokens have been appended,
// or (b) when the parser has no valid non-EOS continuations (dead end). This
// forces the model to generate longer SQL that includes WHERE/JOIN/GROUP BY/
// HAVING before EOS is accepted. A second-stage DeadEndDetection check prevents
// infinite looping in truly dead-end grammar states.
//
// Guidance change: replace the terse "no aliases" instruction with a clause-
// by-clause template ("SELECT ... FROM ... WHERE ... GROUP BY ... HAVING ...
// ORDER BY ...") so the model infers which clauses to generate from the question.
//
// Structure:
//   Phase 1: 5-step unconstrained preamble to emit "SQL: <<" naturally.
//   Phase 2: Force "<<" via OpenConstrainedSpan if not naturally entered.
//   Phase 3: Constrained loop up to min(350, remaining-1) steps; ignore EOS
//             before minTokens=25 constrained tokens unless parser dead-ended.
//   Phase 4: CloseConstrainedSpan (if complete) or CloseSpanWithinBudget(80).
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 preamble: Guard includes !insideConstrainedOut so the implication is
//   vacuous. The only flip to true is when RenderedEndsWith fires; we
//   simultaneously set currentConstrainedOut := []; IsValidPrefix([]) holds by
//   the method precondition.
//
// Phase 2 OpenConstrainedSpan: runs only when !insideConstrainedOut; postcondition
//   sets currentConstrainedOut := []; IsValidPrefix([]) holds by precondition.
//
// Phase 3 inner loop – three token-step branches:
//   (a) EOS, break accepted (>=minTokens or dead end): insideConstrainedOut stays
//       true and currentConstrainedOut is unchanged; invariant carried from
//       previous iteration.
//   (b) EOS, ignored (<minTokens, no dead end): insideConstrainedOut stays true;
//       currentConstrainedOut unchanged; invariant carried.
//   (c) Valid non-EOS token: IsTokenValidNext is true; AppendConstrainedToken
//       postcondition establishes parser.IsValidPrefix(currentConstrainedOut + [next]),
//       so the new currentConstrainedOut is parser-valid.
//
// Phase 4a CloseConstrainedSpan: requires IsCompletePrefix (checked by caller);
//   postcondition sets insideConstrainedOut := false, making the implication
//   vacuously true, and clears currentConstrainedOut := [].
//
// Phase 4b CloseSpanWithinBudget: postcondition directly guarantees
//   insideOut ==> parser.IsValidPrefix(currentOut).
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: Each UnconstrainedStep increments steps by 1 and appends at most 1
//   token (0 for EOS, 1 for non-EOS). Invariant preserved each iteration.
//
// Phase 2: OpenConstrainedSpan increments steps by 1 and appends exactly 1
//   delimiter token. Net 1:1, invariant preserved.
//
// Phase 3: Loop invariant |generated| <= |generatedPrefix| + steps + sqlSteps.
//   Each iteration increments sqlSteps by exactly 1 (one ConstrainedStep call).
//   Branch (a) and (b): generated unchanged, sqlSteps +1. Invariant holds.
//   Branch (c): |generated| +1, sqlSteps +1. Invariant holds.
//   After loop: steps := steps + sqlSteps restores the outer form.
//
// Phase 4a: CloseConstrainedSpan costs +1 step, appends at most 1 ">>" token.
//   |generated| +1, steps +1; invariant preserved.
// Phase 4b: CloseSpanWithinBudget postcondition |generatedOut| <= |generated|
//   + closeBudget; steps += closeBudget; invariant preserved by transitivity.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Write SQL to answer the question. Output format: SQL: <<QUERY>> where QUERY is a syntactically complete SQL statement. For each question: include SELECT with the exact columns asked about; include FROM with the correct table(s) from the schema; add JOIN ... ON ... when the answer requires multiple tables; add WHERE for filter conditions; add GROUP BY + HAVING for aggregation questions (most, average, more than N, count); add ORDER BY for ranking/sorting. Use exact table and column names from the provided schema. Generate all necessary clauses - do not stop after a bare SELECT col FROM table.");

var steps: nat := 0;

// Phase 1: Short unconstrained preamble (up to 5 steps) to emit "SQL: <<" naturally
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Constrained SQL generation with minimum-token EOS guard
// Ignore EOS for the first minTokens constrained tokens to prevent premature
// termination on trivially short SQL. Accept EOS early only on parser dead-end.
var minTokens: nat := 25;
var sqlMaxSteps: nat;
if maxSteps > steps + 1 {
  var headroom := maxSteps - steps - 1; // reserve 1 for close
  if headroom >= 350 {
    sqlMaxSteps := 350;
  } else {
    sqlMaxSteps := headroom;
  }
} else {
  sqlMaxSteps := 0;
}

var sqlSteps: nat := 0;

while sqlSteps < sqlMaxSteps && insideConstrainedOut
  invariant 0 <= sqlSteps <= sqlMaxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps + sqlSteps
  decreases sqlMaxSteps - sqlSteps
{
  var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
  var next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
  sqlSteps := sqlSteps + 1;

  if next == eosToken {
    if |currentConstrainedOut| >= minTokens {
      // Enough SQL content generated; accept EOS and terminate
      break;
    } else {
      // Too short; accept EOS only if parser has no valid non-EOS continuations
      var narrow := helpers.DeadEndDetection(parser, currentConstrainedOut, 1);
      if narrow {
        break; // Dead end: EOS is the only available choice
      }
      // Otherwise ignore EOS and continue to force longer SQL
    }
  } else {
    var valid := helpers.IsTokenValidNext(parser, currentConstrainedOut, next);
    if valid {
      var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}
steps := steps + sqlSteps;

// Phase 4: Close the constrained span
if insideConstrainedOut && steps < maxSteps {
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    var remaining := maxSteps - steps;
    var closeBudget: nat;
    if remaining <= 80 {
      closeBudget := remaining;
    } else {
      closeBudget := 80;
    }
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + closeBudget;
  }
}

cost := steps;

